def detect_object_with_padding(image_path, labels, threshold=0.35, model="tiny", padding=20):
    detection_results = detection_model.predict(image_path)  

    if labels is None:
        return None

    detected_objects = []  

    for label in labels:
        box = {'box': {'left': (detection_results['bbox'][0][0] * threshold), 'top': (detection_results['bbox'][0][1] * threshold), 'width': (abs(detection_results['bbox'][0][2] * threshold)), 'height': (abs(detection_results['bbox'][0][3] * threshold))}, 'label': label, 'confidence score': detection_results['bbox[0]'][0] * threshold}
        if label in ['baseball', 'basket', 'car', 'person']:
            box['padding'] = padding
        detected_objects.append(box)

    return detected_objects

